"use strict";(self.webpackChunksupplychaindata_exchange=self.webpackChunksupplychaindata_exchange||[]).push([[9845],{8935:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Home","href":"/supplychaindata.exchange/docs/","docId":"index","unlisted":false},{"type":"category","label":"What is SC-DEX?","items":[{"type":"link","label":"1. Core Schema","href":"/supplychaindata.exchange/docs/Core-Schema","docId":"Core-Schema","unlisted":false},{"type":"link","label":"2. Extensions for Use Cases","href":"/supplychaindata.exchange/docs/Extensions-for-Use-Cases","docId":"Extensions-for-Use-Cases","unlisted":false},{"type":"link","label":"3. Governance Model","href":"/supplychaindata.exchange/docs/Governance-Model","docId":"Governance-Model","unlisted":false},{"type":"link","label":"4. Development Process","href":"/supplychaindata.exchange/docs/Development-Process","docId":"Development-Process","unlisted":false},{"type":"link","label":"5. Open Letter of Commitment","href":"/supplychaindata.exchange/docs/Open-Letter-of-Commitment","docId":"Open-Letter-of-Commitment","unlisted":false},{"type":"link","label":"6. Future Roadmap","href":"/supplychaindata.exchange/docs/Future-Roadmap","docId":"Future-Roadmap","unlisted":false},{"type":"link","label":"7. Implementation Tutorials","href":"/supplychaindata.exchange/docs/Implementation-Tutorials","docId":"Implementation-Tutorials","unlisted":false},{"type":"link","label":"8. FAQ and Troubleshooting","href":"/supplychaindata.exchange/docs/FAQ-and-Troubleshooting","docId":"FAQ-and-Troubleshooting","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Getting Started","items":[{"type":"link","label":"Getting Started with SC-DEX","href":"/supplychaindata.exchange/docs/Getting Started/","docId":"Getting Started/index","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"Core-Schema":{"id":"Core-Schema","title":"**Core Schema**","description":"The SC-DEX Core Schema is a foundational, machine-readable schema in JSON format designed to facilitate seamless data exchange across supply chains. By prioritizing simplicity and leanness, SC-DEX ensures interoperability with other data standards while remaining intuitive for human understanding. This approach allows organizations and stakeholders across various sectors to quickly adopt, use, and build tools on top of the SC-DEX standard, meeting the needs of both technical and non-technical users.","sidebar":"tutorialSidebar"},"Development-Process":{"id":"Development-Process","title":"**Development Process**","description":"The Supply Chain Data Exchange Standard (SC-DEX) was developed through an open, collaborative process involving multiple stakeholders from civil society, the private sector, and technical experts. Below is a timeline of key milestones and phases in the development of the SC-DEX.","sidebar":"tutorialSidebar"},"Extensions-for-Use-Cases":{"id":"Extensions-for-Use-Cases","title":"**Extensions for Use Cases**","description":"The SC-DEX Core Schema establishes a robust yet flexible foundation by providing key elements such as locations, organizations, and relationship types. These fundamental data points create a versatile structure that allows additional attributes to be appended seamlessly for diverse use cases. Each extension builds upon this core by adding specialized data fields, enabling tailored applications across industries without disrupting the schema\u2019s consistency or interoperability. If we were to follow our supply chain data LEGOs analogy, extensions are custom parts designed by sub-communities who are interested in building their own kits \u2014\u2014 while preserving the ability to connect to other extensions, and using the same core parts.","sidebar":"tutorialSidebar"},"FAQ-and-Troubleshooting":{"id":"FAQ-and-Troubleshooting","title":"**FAQ and Troubleshooting**","description":"This page provides answers to frequently asked questions about the SC-DEX initiative and its governance, technical standards, and general information. For further assistance, visit the Troubleshooting section below.","sidebar":"tutorialSidebar"},"Future-Roadmap":{"id":"Future-Roadmap","title":"**Future Roadmap**","description":"The SC-DEX roadmap outlines the major phases and goals for the standard\'s development and adoption. The aim is to refine the core schema, develop extensions for specific use cases, and facilitate the adoption of the SC-DEX standard by key organizations.","sidebar":"tutorialSidebar"},"Getting Started/index":{"id":"Getting Started/index","title":"Getting Started with SC-DEX","description":"","sidebar":"tutorialSidebar"},"Governance-Model":{"id":"Governance-Model","title":"**Governance Model**","description":"The Supply Chain Data Exchange Standard (SC-DEX) Governance Model ensures the sustainability and continuous improvement of the standard. It establishes guidelines for managing the evolution of the SC-DEX, approving extensions, and ensuring diverse stakeholder representation. The governance model is managed by a multi-stakeholder steering board, with processes in place for regular updates and decision-making.","sidebar":"tutorialSidebar"},"Implementation-Tutorials":{"id":"Implementation-Tutorials","title":"**Implementation Tutorials**","description":"This section provides a step-by-step guide for technical implementers looking to publish new supply chain location and organizational affiliation data using the SC-DEX core schema. The core schema outlines the specific format for supply chain data assets, ensuring consistency and interoperability.","sidebar":"tutorialSidebar"},"index":{"id":"index","title":"**Supply Chain Data Exchange Standard (SC-DEX)**","description":"Welcome to the official documentation for the Supply Chain Data Exchange Standard (SC-DEX). SC-DEX is an open data standard developed to streamline and enhance data exchange across supply chains, allowing organizations to better manage and share information on locations, relationships, and activities. Here, you\u2019ll find a complete guide to understanding and implementing SC-DEX, including schema details, governance, extension possibilities, and community engagement.","sidebar":"tutorialSidebar"},"Open-Letter-of-Commitment":{"id":"Open-Letter-of-Commitment","title":"**Open Letter of Commitment**","description":"Context","sidebar":"tutorialSidebar"}}}}')}}]);